import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"事件 API","description":"","frontmatter":{},"headers":[],"relativePath":"modules/attribute/events.md","filePath":"modules/attribute/events.md","lastUpdated":0}`),a={name:`modules/attribute/events.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="事件-api" tabindex="-1">事件 API <a class="header-anchor" href="#事件-api" aria-label="Permalink to “事件 API”">​</a></h1><p>事件位于 <code>emaki.jiuwu.craft.attribute.api.event</code> 包. 全部事件均为同步派发的可取消 Bukkit 事件, 仅在 runtime 持有事件所需 live target 时发布</p><table tabindex="0"><thead><tr><th>事件</th><th>触发时机</th><th>线程</th><th>可修改字段</th><th>取消效果</th><th>runtime 路径</th></tr></thead><tbody><tr><td><code>EmakiAttributeDamageEvent</code></td><td>伤害计算后, 最终应用前</td><td>target/attacker 共同 owner thread</td><td><code>finalDamage</code></td><td>取消或最终值 <code>&lt;=0</code> 阻止伤害</td><td>damage application service; 纯 <code>calculateDamage</code> 不发</td></tr><tr><td><code>PlayerResourceConsumeEvent</code></td><td>资源扣减前</td><td>玩家 owner thread</td><td><code>amount</code></td><td>阻止扣减, 公开操作返回取消失败</td><td><code>consumeResource</code> 与进入同一 service 的 runtime 路径</td></tr><tr><td><code>PlayerAttributePointAllocateEvent</code></td><td>属性点分配提交前</td><td>玩家 owner thread</td><td><code>amount</code></td><td>阻止分配</td><td><code>ParentAttributeService</code> 分配路径</td></tr><tr><td><code>PlayerAttributePointResetEvent</code></td><td>重置提交前</td><td>玩家 owner thread</td><td>无</td><td>阻止重置</td><td><code>ParentAttributeService</code> 重置路径</td></tr></tbody></table><p>监听器修改的值在监听器返回后重新校验. 非 owner/异步路径不得把 Bukkit 事件 off-thread 发出; 需要可靠拦截时先用 owner scheduler 调度. 第三方 provider/gate 不在 event 包, 而位于 <code>emaki.jiuwu.craft.attribute.api.extension</code></p>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};